To add SoundCloud music playback to your website, here's a structured solution using SoundCloud's oEmbed and JavaScript API. This approach is secure and efficient:

### Solution Code
```html
<!DOCTYPE html>
<html>
<head>
    <title>SoundCloud Player</title>
    <style>
        #player-container {
            max-width: 600px;
            margin: 20px auto;
            padding: 15px;
            border: 1px solid #ccc;
            border-radius: 8px;
            box-shadow: 0 0 10px rgba(0,0,0,0.1);
            text-align: center;
        }
        #player {
            margin: 15px 0;
        }
    </style>
</head>
<body>
    <div id="player-container">
        <input type="text" id="trackUrl" placeholder="SoundCloud Track URL or ID">
        <button onclick="loadTrack()">Load Track</button>
        <div id="player"></div>
    </div>

    <script>
        const CLIENT_ID = 'YOUR_CLIENT_ID'; // Replace with your actual client ID
        let currentPlayer = null;

        // Load track by URL or ID
        function loadTrack() {
            const input = document.getElementById('trackUrl').value.trim();
            if (!input) return alert('Please enter a valid SoundCloud URL or Track ID');

            // Reset previous player
            const playerDiv = document.getElementById('player');
            playerDiv.innerHTML = '';

            // Resolve track URL to ID if necessary
            if (input.startsWith('http')) {
                resolveTrackId(input);
            } else if (/^\d+$/.test(input)) {
                createPlayer(input);
            } else {
                alert('Invalid input. Please use a valid URL or numeric ID.');
            }
        }

        // Resolve SoundCloud URL to Track ID using resolve endpoint
        function resolveTrackId(url) {
            const encodedUrl = encodeURIComponent(url);
            fetch(`https://api.soundcloud.com/resolve?url=${encodedUrl}&client_id=${CLIENT_ID}`)
                .then(response => response.json())
                .then(data => {
                    if (data.id) {
                        createPlayer(data.id);
                    } else {
                        throw new Error(data.error || 'Track not found');
                    }
                })
                .catch(error => {
                    alert(`Error: ${error.message}`);
                    console.error('Resolve Error:', error);
                });
        }

        // Create embedded player
        function createPlayer(trackId) {
            const playerDiv = document.getElementById('player');
            const iframe = document.createElement('iframe');

            iframe.width = '100%';
            iframe.height = '166';
            iframe.frameBorder = '0';
            iframe.allow = 'autoplay';

            const params = new URLSearchParams({
                url: `https://api.soundcloud.com/tracks/${trackId}`,
                client_id: CLIENT_ID,
                auto_play: 'false',
                hide_related: 'true',
                show_comments: 'false',
                show_user: 'false',
                show_reposts: 'false'
            });

            iframe.src = `https://w.soundcloud.com/player/?${params.toString()}`;
            playerDiv.appendChild(iframe);
        }

        // Clean up existing player (important for memory management)
        window.addEventListener('beforeunload', () => {
            if (currentPlayer) {
                currentPlayer.destroy();
            }
        });
    </script>
</body>
</html>
```

